from flask import Flask, render_template_string, request
from flask_socketio import SocketIO, emit
import eventlet
eventlet.monkey_patch()
app = Flask(__name__)
app.config['SECRET_KEY'] = 'codm_v2_ultra_fixed'
socketio = SocketIO(app, cors_allowed_origins='*', async_mode='eventlet')
PLAYERS={}
HTML='''<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CODM V2 Ultra FIXED</title>
<style>*{margin:0;padding:0;box-sizing:border-box;font-family:'Segoe UI',sans-serif}html,body{width:100%;height:100%;overflow:hidden;background:#000;color:#fff}#canvas{width:100%;height:100%;position:absolute;top:0;left:0}#auth{position:absolute;width:100%;height:100%;background:radial-gradient(#222,#000);display:flex;justify-content:center;align-items:center;z-index:99}.card{background:#111;border:2px solid #ff7700;padding:30px;border-radius:10px;width:340px;text-align:center;box-shadow:0 0 25px rgba(255,119,0,.4)}h1{color:#ff7700;margin-bottom:20px;letter-spacing:2px}.card input{width:100%;padding:14px;background:#222;color:#fff;border:1px solid #444;border-radius:4px;margin:10px 0}.card button{width:100%;padding:14px;background:#ff7700;border:none;font-weight:bold;border-radius:4px}#hud{position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;display:none}.interactive{pointer-events:auto}#crosshair{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:14px;height:14px;border:1px solid #0f0;border-radius:50%}#crosshair:after{content:'';position:absolute;top:6px;left:6px;width:2px;height:2px;background:#0f0;border-radius:50%}#tl{position:absolute;top:15px;left:15px;display:flex;flex-direction:column;gap:6px}.panel{background:rgba(0,0,0,.7);border-left:3px solid #ff7700;padding:8px 12px;border-radius:3px;font-size:13px}#weapon{position:absolute;bottom:15px;right:15px;background:rgba(0,0,0,.8);padding:12px;border-right:3px solid #ff7700;text-align:right;border-radius:4px}#wt{color:#ff7700;font-weight:bold}#ammo{font-size:22px;font-weight:bold}#action{position:absolute;top:60%;left:50%;transform:translate(-50%,-50%);background:#ff7700;color:#000;padding:12px 24px;border-radius:20px;border:none;font-weight:bold;display:none}#joystick{position:absolute;bottom:25px;left:25px;width:120px;height:120px;background:rgba(255,255,255,.08);border-radius:50%;border:1px solid rgba(255,255,255,.2);display:none}#knob{position:absolute;top:35px;left:35px;width:50px;height:50px;background:rgba(255,119,0,.8);border-radius:50%}#fire{position:absolute;bottom:35px;right:25px;width:75px;height:75px;background:rgba(255,0,0,.55);border:2px solid #f44;border-radius:50%;display:none;align-items:center;justify-content:center;font-weight:bold}#flash{position:absolute;top:0;left:0;width:100%;height:100%;background:rgba(255,0,0,.3);pointer-events:none;opacity:0}#feed{position:absolute;top:110px;right:15px;width:200px;font-size:11px;text-align:right}#feed div{background:rgba(0,0,0,.6);padding:3px 6px;margin-bottom:3px;border-right:2px solid red}
</style><script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/socket.io/4.7.2/socket.io.min.js"></script></head><body>
<div id="auth"><div class="card"><h1>CODM V2 ULTRA</h1><input id="name" placeholder="Operator name"><button onclick="start()">DEPLOY</button><p style="font-size:10px;color:#888;margin-top:10px">FPS + 10 Bots + HD Map + AK Model</p></div></div>
<div id="canvas"></div><div id="flash"></div>
<div id="hud"><div id="crosshair"></div><div id="tl"><div class="panel">OP: <span id="un" style="color:#ff7700">-</span></div><div class="panel">HP: <span id="hp" style="color:#0f0">100</span> | ARMOR: <span style="color:#0cf">50</span></div><div class="panel"><span id="st">IN PLANE</span></div></div><div id="weapon"><div id="wt">AK-47 TACTICAL</div><div id="ammo">30 / 30</div></div><div id="feed"></div><button id="action" class="interactive" onclick="jump()">JUMP (SPACE)</button><div id="joystick" class="interactive"><div id="knob"></div></div><div id="fire" class="interactive">FIRE</div></div>
<script>
let socket,scene,camera,renderer,playerGroup,plane,parachute,gunGroup,muzzleLight,bots=[],otherPlayers={},keys={},state='PLANE',hp=100,weapon={ammo:30,max:30,dmg:35,rate:110},last=0,kills=0;
function start(){let n=document.getElementById('name').value.trim();if(!n)return alert('Enter name');document.getElementById('un').innerText=n;document.getElementById('auth').style.display='none';document.getElementById('hud').style.display='block';init();initSocket();if('ontouchstart' in window){document.getElementById('joystick').style.display='block';document.getElementById('fire').style.display='flex';setupMobile();}}
function initSocket(){socket=io();socket.on('connect',()=>{socket.emit('player_join',{username:document.getElementById('un').innerText});});socket.on('current_players',d=>{for(let id in d)if(id!==socket.id)spawnOther(id,d[id]);});socket.on('player_joined',d=>spawnOther(d.id,d));socket.on('player_moved',d=>{if(otherPlayers[d.id])otherPlayers[d.id].position.set(d.x,d.y,d.z);});socket.on('player_disconnected',id=>{if(otherPlayers[id]){scene.remove(otherPlayers[id]);delete otherPlayers[id];}});}
function init(){scene=new THREE.Scene();scene.background=new THREE.Color(0x8ab8ff);scene.fog=new THREE.FogExp2(0x8ab8ff,0.004);camera=new THREE.PerspectiveCamera(75,innerWidth/innerHeight,0.1,1000);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;document.getElementById('canvas').appendChild(renderer.domElement);scene.add(new THREE.AmbientLight(0xffffff,0.7));let sun=new THREE.DirectionalLight(0xffffff,0.9);sun.position.set(100,200,50);sun.castShadow=true;scene.add(sun);let ground=new THREE.Mesh(new THREE.PlaneGeometry(1000,1000),new THREE.MeshLambertMaterial({color:0x3a7d44}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);build();makePlane();makePlayer();spawnBots();addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='Space')jump();if(e.code==='KeyR')reload();});addEventListener('keyup',e=>keys[e.code]=false);addEventListener('mousedown',shoot);document.getElementById('action').style.display='block';loop();}
function build(){for(let i=0;i<20;i++){let h=10+Math.random()*12,w=12+Math.random()*8;let b=new THREE.Mesh(new THREE.BoxGeometry(w,h,w),new THREE.MeshStandardMaterial({color: i%3==0?0x9a9a9a: i%3==1?0x6b4423:0x4a4a4a}));let ang=(i/20)*Math.PI*2,dist=100+Math.random()*200;b.position.set(Math.cos(ang)*dist,h/2,Math.sin(ang)*dist);b.castShadow=true;scene.add(b);let win=new THREE.Mesh(new THREE.BoxGeometry(2,2,0.2),new THREE.MeshBasicMaterial({color:0x87ceeb}));win.position.set(0,2,w/2+0.1);b.add(win);}}
function makePlane(){plane=new THREE.Group();plane.add(new THREE.Mesh(new THREE.BoxGeometry(36,5,7),new THREE.MeshStandardMaterial({color:0x5a5a5a})));plane.add(new THREE.Mesh(new THREE.BoxGeometry(12,1,18),new THREE.MeshStandardMaterial({color:0x777})));plane.position.set(-400,180,0);scene.add(plane);}
function makePlayer(){playerGroup=new THREE.Group();gunGroup=new THREE.Group();let rec=new THREE.Mesh(new THREE.BoxGeometry(0.25,0.35,1.6),new THREE.MeshStandardMaterial({color:0x111}));rec.position.set(0.35,-0.35,-0.9);let barrel=new THREE.Mesh(new THREE.BoxGeometry(0.08,0.08,1.1),new THREE.MeshStandardMaterial({color:0x333}));barrel.position.set(0.35,-0.28,-1.9);let sight=new THREE.Mesh(new THREE.BoxGeometry(0.12,0.12,0.2),new THREE.MeshStandardMaterial({color:0x222}));sight.position.set(0.35,-0.1,-0.9);gunGroup.add(rec,barrel,sight);muzzleLight=new THREE.PointLight(0xff9900,0,6);muzzleLight.position.set(0.35,-0.28,-2.5);gunGroup.add(muzzleLight);camera.add(gunGroup);playerGroup.add(camera);playerGroup.position.set(-400,180,0);parachute=new THREE.Mesh(new THREE.ConeGeometry(4.5,2.5,8),new THREE.MeshBasicMaterial({color:0xffffff,wireframe:true}));parachute.position.y=4.5;parachute.visible=false;playerGroup.add(parachute);scene.add(playerGroup);}
function spawnBots(){for(let i=0;i<10;i++){let m=new THREE.Group();let body=new THREE.Mesh(new THREE.BoxGeometry(0.9,1.6,0.5),new THREE.MeshStandardMaterial({color:0xcc2222}));let head=new THREE.Mesh(new THREE.BoxGeometry(0.5,0.5,0.5),new THREE.MeshStandardMaterial({color:0xffdbac}));head.position.y=1.05;let gun=new THREE.Mesh(new THREE.BoxGeometry(0.1,0.1,0.8),new THREE.MeshStandardMaterial({color:0x111}));gun.position.set(0.3,0.2,-0.4);m.add(body,head,gun);m.position.set((Math.random()-0.5)*400,0.8,(Math.random()-0.5)*400);m.userData={hp:100,dir:Math.random()*Math.PI*2};scene.add(m);bots.push(m);}}
function spawnOther(id,data){let m=new THREE.Mesh(new THREE.BoxGeometry(0.9,1.8,0.5),new THREE.MeshStandardMaterial({color:0x0066ff}));m.position.set(data.x||0,data.y||0.9,data.z||0);scene.add(m);otherPlayers[id]=m;}
function jump(){if(state!=='PLANE')return;state='PARACHUTE';playerGroup.position.copy(plane.position);parachute.visible=true;document.getElementById('st').innerText='PARACHUTING';document.getElementById('action').style.display='none';}
function reload(){weapon.ammo=weapon.max;document.getElementById('ammo').innerText=weapon.ammo+' / '+weapon.max;}
function shoot(){if(state!=='GROUND')return;let now=Date.now();if(now-last<weapon.rate||weapon.ammo<=0){if(weapon.ammo<=0)reload();return;}weapon.ammo--;last=now;document.getElementById('ammo').innerText=weapon.ammo+' / '+weapon.max;muzzleLight.intensity=5;setTimeout(()=>muzzleLight.intensity=0,50);let rc=new THREE.Raycaster();rc.setFromCamera(new THREE.Vector2(0,0),camera);let targets=[];bots.forEach(b=>{b.children.forEach(c=>targets.push(c));});Object.values(otherPlayers).forEach(o=>targets.push(o));let hits=rc.intersectObjects(targets,true);if(hits.length>0){let obj=hits[0].object;let root=obj.parent;while(root.parent&&root.parent!==scene)root=root.parent;if(bots.includes(root)){root.userData.hp-=weapon.dmg;if(root.userData.hp<=0){root.position.set((Math.random()-0.5)*400,0.8,(Math.random()-0.5)*400);root.userData.hp=100;kills++;addFeed('BOT ELIMINATED +' + kills);}else{root.material&& (root.children[0].material.color.set(0xffffff));setTimeout(()=>{if(root.children[0])root.children[0].material.color.set(0xcc2222);},100);}}else{for(let id in otherPlayers){if(otherPlayers[id]===obj||otherPlayers[id]===root){socket.emit('shoot_player',{targetId:id,damage:weapon.dmg});break;}}}}}
function addFeed(t){let f=document.getElementById('feed');let d=document.createElement('div');d.innerText=t;f.prepend(d);setTimeout(()=>d.remove(),3500);}
function loop(){requestAnimationFrame(loop);if(state==='PLANE'){plane.position.x+=1.7;if(plane.position.x>400)plane.position.x=-400;playerGroup.position.copy(plane.position);camera.position.set(0,6,18);camera.lookAt(plane.position);}else if(state==='PARACHUTE'){playerGroup.position.y-=0.5;if(keys['KeyW'])playerGroup.position.z-=0.6;if(keys['KeyS'])playerGroup.position.z+=0.6;if(keys['KeyA'])playerGroup.position.x-=0.6;if(keys['KeyD'])playerGroup.position.x+=0.6;camera.position.set(0,9,22);if(playerGroup.position.y<=1){playerGroup.position.y=0.9;state='GROUND';parachute.visible=false;document.getElementById('st').innerText='COMBAT';}}else if(state==='GROUND'){let sp=keys['ShiftLeft']?0.65:0.35;if(keys['KeyW'])playerGroup.translateZ(-sp);if(keys['KeyS'])playerGroup.translateZ(sp);if(keys['KeyA'])playerGroup.translateX(-sp);if(keys['KeyD'])playerGroup.translateX(sp);playerGroup.position.y=0.9;bots.forEach(b=>{b.userData.dir+= (Math.random()-0.5)*0.05;b.position.x+= Math.cos(b.userData.dir)*0.12;b.position.z+= Math.sin(b.userData.dir)*0.12;let dist=b.position.distanceTo(playerGroup.position);if(dist<25){b.lookAt(playerGroup.position);}});if(socket)socket.emit('player_move',{x:playerGroup.position.x,y:playerGroup.position.y,z:playerGroup.position.z});}renderer.render(scene,camera);}
function setupMobile(){let zone=document.getElementById('joystick'),knob=document.getElementById('knob'),fire=document.getElementById('fire'),sx=0,sy=0,act=false;zone.addEventListener('touchstart',e=>{act=true;sx=e.touches[0].clientX;sy=e.touches[0].clientY;});zone.addEventListener('touchmove',e=>{if(!act)return;let dx=e.touches[0].clientX-sx,dy=e.touches[0].clientY-sy,d=Math.sqrt(dx*dx+dy*dy);if(d>45){dx=dx/d*45;dy=dy/d*45;}knob.style.transform='translate('+dx+'px,'+dy+'px)';let mx=dx/45,my=dy/45;if(state==='GROUND'){playerGroup.translateX(mx*0.5);playerGroup.translateZ(my*0.5);}else if(state==='PARACHUTE'){playerGroup.position.x+=mx*0.5;playerGroup.position.z+=my*0.5;}e.preventDefault();},{passive:false});zone.addEventListener('touchend',()=>{act=false;knob.style.transform='translate(0,0)';});fire.addEventListener('touchstart',e=>{e.preventDefault();shoot();});}
</script></body></html>'''
@app.route('/')
def home():
    return render_template_string(HTML)
@socketio.on('player_join')
def join(d):
    PLAYERS[request.sid]={'username':d['username'],'x':0,'y':0.9,'z':0}
    emit('current_players', PLAYERS, to=request.sid)
    emit('player_joined', {'id':request.sid, **PLAYERS[request.sid]}, broadcast=True, include_self=False)
@socketio.on('player_move')
def move(d):
    if request.sid in PLAYERS:
        PLAYERS[request.sid].update(d)
        emit('player_moved', {'id':request.sid, **d}, broadcast=True, include_self=False)
@socketio.on('shoot_player')
def shoot(d):
    emit('player_shot_event', {'targetId':d.get('targetId'),'damage':d.get('damage',35)}, broadcast=True)
@socketio.on('disconnect')
def disc():
    PLAYERS.pop(request.sid, None)
    emit('player_disconnected', request.sid, broadcast=True)
if __name__=='__main__':
    socketio.run(app, host='0.0.0.0', port=10000)
